import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.RQXGjTIX.js";const u=JSON.parse('{"title":"常见问题与已知限制","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),i={name:"guide/faq.md"};function l(s,e,d,n,c,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="常见问题与已知限制" tabindex="-1">常见问题与已知限制 <a class="header-anchor" href="#常见问题与已知限制" aria-label="Permalink to &quot;常见问题与已知限制&quot;">​</a></h1><h2 id="为什么元件存气体却不显示压力" tabindex="-1">为什么元件存气体却不显示压力？ <a class="header-anchor" href="#为什么元件存气体却不显示压力" aria-label="Permalink to &quot;为什么元件存气体却不显示压力？&quot;">​</a></h2><p>因为元件只保存<strong>数量</strong>。压力是“数量 ÷ 体积”的推导量，而 ME 网络里没有“体积”这个概念。 真实的压力交接发生在 <a href="/appliedcraftedenergistics/guide/interface.html">ME 气体接口</a> 的槽位容器和 <a href="/appliedcraftedenergistics/guide/p2p.html">气体 P2P 隧道</a> 的缓冲罐里。</p><h2 id="_1-byte-到底是多少气体" tabindex="-1">1 byte 到底是多少气体？ <a class="header-anchor" href="#_1-byte-到底是多少气体" aria-label="Permalink to &quot;1 byte 到底是多少气体？&quot;">​</a></h2><p><strong>1 AE byte = 1,000 GU = 1,000 升 @ 100 kPa（1 atm）</strong>。 所以 1k 元件（1,024 字节）= 1,024,000 GU = 1,024 m³ 常压气体； 1M 元件（1,048,576 字节）= 1,048,576,000 GU。</p><h2 id="装了升级卡后元件显示的容量为什么变大" tabindex="-1">装了升级卡后元件显示的容量为什么变大？ <a class="header-anchor" href="#装了升级卡后元件显示的容量为什么变大" aria-label="Permalink to &quot;装了升级卡后元件显示的容量为什么变大？&quot;">​</a></h2><p>升级卡提高的是<strong>该元件的字节上限</strong>。<code>1 byte = 1,000 GU</code> 的全局规则不变， 只是这只元件现在有更多字节可用。详见 <a href="/appliedcraftedenergistics/guide/upgrades.html">元件升级卡</a>。</p><h2 id="为什么-1m–256m-元件没有配方" tabindex="-1">为什么 1M–256M 元件没有配方？ <a class="header-anchor" href="#为什么-1m–256m-元件没有配方" aria-label="Permalink to &quot;为什么 1M–256M 元件没有配方？&quot;">​</a></h2><p>这些元件的默认配方以 <strong>MEGA Cells</strong> 为前置，并且带 <code>neoforge:mod_loaded</code> 条件： <strong>只有安装 MEGA Cells 时，默认配方才会加载和显示</strong>。</p><ul><li>想用默认配方：安装 MEGA Cells 4.11.x；</li><li>不想装 MEGA：用数据包覆盖 <code>data/appliedcraftedenergistics/recipe/gas_cell_*.json</code>；</li><li>想移除默认配方：把 <code>recipes.enable_mega_cell_recipes</code> 设为 <code>false</code>。</li></ul><p>元件本身始终注册，可由创造模式或命令获得。详见 <a href="/appliedcraftedenergistics/guide/config.html">配置文件</a>。</p><h2 id="原版-me-接口能处理气体吗" tabindex="-1">原版 ME 接口能处理气体吗？ <a class="header-anchor" href="#原版-me-接口能处理气体吗" aria-label="Permalink to &quot;原版 ME 接口能处理气体吗？&quot;">​</a></h2><p>可以。0.2.2 通过 <code>AeInterfaceGasCompat</code> 为原版 <code>ae2:interface</code> 注册气体能力： 它的槽位以固定 100 kPa 容器暴露给 CCB 管道，管道可以从接口抽气。 ACE 自己的 ME 气体接口额外提供逐槽目标数量、目标压力和传输模式。</p><h2 id="气体接口的槽位怎么设置" tabindex="-1">气体接口的槽位怎么设置？ <a class="header-anchor" href="#气体接口的槽位怎么设置" aria-label="Permalink to &quot;气体接口的槽位怎么设置？&quot;">​</a></h2><ul><li><strong>点击配置槽上方的设置按钮</strong>，或<strong>中键点击</strong>配置槽：打开逐槽设置界面；</li><li>设置界面可编辑<strong>目标数量</strong>、<strong>目标压力</strong>和（安装逐槽控制卡后）<strong>传输模式</strong>；</li><li>右键配置槽（手持气体样本 / CCB 气体容器）：标记气体；</li><li>安装 JEI 时也可以从 JEI 拖拽气体 ingredient 到配置槽。</li></ul><h2 id="为什么接口在排气" tabindex="-1">为什么接口在排气？ <a class="header-anchor" href="#为什么接口在排气" aria-label="Permalink to &quot;为什么接口在排气？&quot;">​</a></h2><p>安装了<strong>安全卡</strong>（<code>safety_valve_card</code>）且某个槽位压力达到 20 atm 时会自动泄压。这是真实排气： 气体通过 CCB 的释放机制排到环境中，会推动附近实体。正常目标压力（≤16 atm）不会触发； 如果频繁排气，请检查该槽位的目标压力与外部管网压力。</p><blockquote><p>元件上的 <code>relief_valve_card</code> 中文名是 <strong>泄压阀卡</strong>，与本接口的 <strong>安全卡</strong> 不同。</p></blockquote><h2 id="输入-输出总线的目标压力怎么设置" tabindex="-1">输入/输出总线的目标压力怎么设置？ <a class="header-anchor" href="#输入-输出总线的目标压力怎么设置" aria-label="Permalink to &quot;输入/输出总线的目标压力怎么设置？&quot;">​</a></h2><p>在总线里安装 <strong>气体压力卡</strong>（<code>gas_pressure_card</code>）： 输出总线只输出到目标压力，输入总线只在高于目标压力时抽取；右键循环预设，潜行右键回退。</p><h2 id="气体自动合成在重载存档后失败" tabindex="-1">气体自动合成在重载存档后失败？ <a class="header-anchor" href="#气体自动合成在重载存档后失败" aria-label="Permalink to &quot;气体自动合成在重载存档后失败？&quot;">​</a></h2><p>0.2.2 已修复：<code>GasKey</code> 使用注册表里的规范 Gas 对象作为 AE2 主键，保存并重载世界后合成计划的 Key 查找仍然稳定。 如果仍遇到问题，请带上存档、<code>crash-reports/</code> 和 <code>logs/latest.log</code> 反馈。</p><h2 id="与-applied-pneumatics-pneumaticcraft-冲突吗" tabindex="-1">与 Applied Pneumatics / PneumaticCraft 冲突吗？ <a class="header-anchor" href="#与-applied-pneumatics-pneumaticcraft-冲突吗" aria-label="Permalink to &quot;与 Applied Pneumatics / PneumaticCraft 冲突吗？&quot;">​</a></h2><p>不冲突。已在同一 183 模组整合包中同时加载 <code>Applied Pneumatics 1.0.9</code>、<code>PneumaticCraft 8.2.24</code> 与本模组并启动验证；三者各自注册自己的 key type / 能力，互不覆盖。</p><h2 id="游戏崩溃了-报告里出现-gasbuffertank-1-或类似的-noclassdeffounderror" tabindex="-1">游戏崩溃了，报告里出现 <code>GasBufferTank$1</code> 或类似的 <code>NoClassDefFoundError</code> <a class="header-anchor" href="#游戏崩溃了-报告里出现-gasbuffertank-1-或类似的-noclassdeffounderror" aria-label="Permalink to &quot;游戏崩溃了，报告里出现 `GasBufferTank$1` 或类似的 `NoClassDefFoundError`&quot;">​</a></h2><p>先确认是不是<strong>在游戏运行中替换了 mod 的 jar</strong>。在运行中的实例里覆盖 jar，会让 JVM 打开的文件 与磁盘内容错位，随后任何一次懒加载都会失败（常见表现：玩一段时间后崩在某个方块实体上）。 处理方式：完全退出游戏 → 重新启动即可；同时以后替换 jar 前先关游戏。</p><p>如果重启后仍然复现，请带上 <code>crash-reports/</code> 与 <code>logs/latest.log</code> 到 <a href="https://github.com/DaKang233/AppliedCraftedEnergistics/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 反馈。</p><h2 id="已知限制-0-2-2" tabindex="-1">已知限制（0.2.2） <a class="header-anchor" href="#已知限制-0-2-2" aria-label="Permalink to &quot;已知限制（0.2.2）&quot;">​</a></h2><ul><li>便携式气体元件尚未实现；</li><li>不支持“按气体族系过滤”的分区（模糊卡对气体无意义）；</li><li>标准 AE2 处理样板不携带目标压力，压力仍由机器/容器决定；</li><li>1M–256M 的默认配方需要 MEGA Cells；不装 MEGA 时需要自定义数据包；</li><li>气体的配方以简化配方为主，不追求数值平衡。</li></ul><h2 id="反馈" tabindex="-1">反馈 <a class="header-anchor" href="#反馈" aria-label="Permalink to &quot;反馈&quot;">​</a></h2><ul><li>源码与问题追踪：<a href="https://github.com/DaKang233/AppliedCraftedEnergistics" target="_blank" rel="noreferrer">GitHub</a></li><li>下载：<a href="https://github.com/DaKang233/AppliedCraftedEnergistics/releases" target="_blank" rel="noreferrer">GitHub Releases</a></li><li>许可证：<strong>LGPL v3.0</strong>（SPDX: <code>LGPL-3.0-only</code>），详见 <a href="/appliedcraftedenergistics/guide/license.html">许可与第三方声明</a>。</li></ul>',31)])])}const f=a(i,[["render",l]]);export{u as __pageData,f as default};
